int DatasetLocal::Compare(const Timestamp *aCompare)
{
    int rval = 1;

    if (aCompare == NULL)
    {
        if (!mTimestampPresent)
        {
            rval = 0;
        }
        else
        {
            rval = -1;
        }
    }
    else
    {
        if (!mTimestampPresent)
        {
            rval = 1;
        }
        else
        {
            rval = mTimestamp.Compare(*aCompare);
        }
    }

    return rval;
}
